composeOverride:
# Generated by McHarbor App Store
services:
  {{serviceName}}:
    image: {{image}}
    container_name: {{containerName}}
    restart: unless-stopped
{{ports}}
    environment:
      TZ: {{env.TZ}}
      PACT_BROKER_DATABASE_HOST: "{{serviceName}}-postgres"
      PACT_BROKER_DATABASE_NAME: pactbroker
      PACT_BROKER_DATABASE_USERNAME: {{env.PACT_BROKER_DATABASE_USERNAME}}
      PACT_BROKER_DATABASE_PASSWORD: {{env.PACT_BROKER_DATABASE_PASSWORD}}
      PACT_BROKER_BASIC_AUTH_USERNAME: {{env.PACT_BROKER_BASIC_AUTH_USERNAME}}
      PACT_BROKER_BASIC_AUTH_PASSWORD: {{env.PACT_BROKER_BASIC_AUTH_PASSWORD}}
    depends_on:
      - {{serviceName}}-postgres
  {{serviceName}}-postgres:
    image: postgres:16-alpine
    container_name: {{serviceName}}-postgres
    restart: unless-stopped
    environment:
      POSTGRES_USER: pactbroker
      POSTGRES_PASSWORD: {{env.PACT_BROKER_DATABASE_PASSWORD}}
      POSTGRES_DB: pactbroker
    volumes:
      - {{appDataPath}}/postgres:/var/lib/postgresql/data
